def _lowpass(a):
    # cheap large-radius low-pass: downscale to ~128 wide, back up
    img = Image.fromarray((np.clip(a, 0, 1) * 255).astype(np.uint8), "RGB")
    lo = img.resize((128, max(1, round(128 * a.shape[0] / a.shape[1]))), Image.LANCZOS)
    return np.asarray(lo.resize((a.shape[1], a.shape[0]), Image.BILINEAR),
